package com.workplace.mail.dto;

import java.util.List;

/**
 * 본문 전용 파싱 결과(OnDemand/백그라운드 본문 적재용).
 *
 * @param autoGenerated WP-149 ② 대량·자동 발송 헤더 판정 결과(헤더 원문은 저장하지 않음)
 * @param calendarIcs WP-986 메일에 실린 iCalendar 원문(text/calendar 파트 또는 .ics 첨부의 첫 번째). 없으면 null — 초대
 *     카드 재료
 * @param senderEmails WP-986 메일 From·Sender 헤더의 주소(소문자) — 초대가 주최자가 보낸 메일인지 판정한다. 없으면 빈 목록
 */
public record ParsedBody(
    String bodyText,
    String bodyHtml,
    String snippet,
    boolean hasAttachment,
    List<ParsedAttachment> attachments,
    boolean autoGenerated,
    String calendarIcs,
    List<String> senderEmails) {

  public ParsedBody {
    senderEmails = senderEmails == null ? List.of() : List.copyOf(senderEmails);
  }

  /** iCalendar 없이 생성(기존 호출·테스트 호환). */
  public ParsedBody(
      String bodyText,
      String bodyHtml,
      String snippet,
      boolean hasAttachment,
      List<ParsedAttachment> attachments,
      boolean autoGenerated) {
    this(bodyText, bodyHtml, snippet, hasAttachment, attachments, autoGenerated, null, List.of());
  }
}
